// FITmeAyurveda.swift
// One-file FITme Ayurveda module: models, data layer, SwiftUI screens and all data.
//
// HOW TO USE
//   1. Drag this file into Xcode (tick "Copy items if needed" and your app target).
//   2. Show it, e.g. as a tab:
//        AyurvedaHomeView()
//            .environmentObject(AyurvedaStore())
//            .tabItem { Label("Ayurveda", systemImage: "leaf") }
//   Requires iOS 16+. Works offline; no network calls.
//
// DATA (embedded at the bottom of this file)
//   - 15 everyday complaints, 168 classical Ayurvedic options (Ministry of AYUSH
//     Ayurvedic Standard Treatment Guidelines, 2017), English + Hindi
//   - 113 herbs / formulations / bhasmas with safety flags and medicine interactions
//   - 2,626 medicines with aliases for search and label scanning
//
// Generated by fitme-ayurveda-data/build_ios_single_file.py. Edit the sources and
// regenerate rather than editing the embedded JSON by hand.
//
// General safety information only, not medical advice.

import Foundation
#if canImport(SwiftUI)
import SwiftUI
#endif

// MARK: - ======================== Models ========================

// MARK: - Ayurvedic options for minor complaints (AyurvedaOTC.json)

struct OTCFile: Decodable {
    let version: String
    let disclaimer: String
    let complaints: [OTCComplaint]
}

struct OTCComplaint: Decodable, Identifiable, Hashable {
    let id: String
    let title: String
    let titleHi: String?
    let otcMedicinesUsuallyUsed: String
    let seeADoctorIf: String
    let source: String
    let options: [OTCOption]
}

struct OTCOption: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    let nameHi: String?
    let form: String
    let howUsed: String
    let caution: String
}

// MARK: - Herb safety (HerbSafety.json)

struct HerbFile: Decodable {
    let version: String
    let disclaimer: String
    let drugClassLabels: [String: String]
    let herbs: [Herb]
}

enum Severity: String, Decodable, Comparable, CaseIterable {
    case major, moderate, minor

    var rank: Int {
        switch self {
        case .major: return 3
        case .moderate: return 2
        case .minor: return 1
        }
    }

    var title: String {
        switch self {
        case .major: return "Major"
        case .moderate: return "Moderate"
        case .minor: return "Minor"
        }
    }

    var subtitle: String {
        switch self {
        case .major: return "Avoid unless your doctor says it's fine"
        case .moderate: return "Check with your doctor first"
        case .minor: return "Lower-evidence interactions"
        }
    }

    static func < (lhs: Severity, rhs: Severity) -> Bool { lhs.rank < rhs.rank }
}

struct Herb: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    let nameHi: String?
    let sanskrit: String?
    let latin: String?
    let otherNames: [String]
    let kind: String
    let dataQuality: String
    let traditionalContext: String?
    let isAyurvedic: Bool
    let commonProducts: [String]
    let safetyFlags: [SafetyFlag]
    let interactions: [Interaction]
    let herbWarnings: [HerbLevelWarning]

    var kindLabel: String {
        switch kind {
        case "herb": return "Herb"
        case "food_spice": return "Spice / food"
        case "formulation": return "Formulation"
        case "mineral_preparation": return "Bhasma / mineral"
        default: return kind
        }
    }
}

struct SafetyFlag: Decodable, Hashable {
    let flag: String
    let note: String
    let evidence: String
    let sources: [String]
}

struct Interaction: Decodable, Hashable {
    let drugClass: String
    let severity: Severity
    let effect: String
    let mechanism: String?
    let evidence: String?
    let advice: String?
    let sources: [String]
    /// When set, this interaction applies only to these molecules, not the whole class.
    let onlyMolecules: [String]?
    /// When set, only these molecules get "major"; the rest of the class gets "moderate".
    let majorOnlyFor: [String]?
}

struct HerbLevelWarning: Decodable, Hashable {
    let severity: Severity
    let effect: String
    let sources: [String]
}

// MARK: - Medicines (Medicines.json)

struct MedicineFile: Decodable {
    let version: String
    let medicines: [Medicine]
}

struct Medicine: Decodable, Identifiable, Hashable {
    /// Lower-case generic molecule name, e.g. "warfarin".
    let id: String
    let name: String
    let classes: [String]
    let aliases: [String]
    let inNLEM: Bool
}

// MARK: - Result of matching a medicine against herbs

struct HerbWarning: Identifiable, Hashable {
    let herb: Herb
    let interaction: Interaction
    /// Severity after molecule-specific rules were applied.
    let severity: Severity

    var id: String { herb.id + "|" + interaction.drugClass }
}

// MARK: - ======================== Data layer ========================

/// Loads the bundled Ayurveda JSON files and answers lookups. Pure Foundation, no UI,
/// so it can run off the main thread and be unit-tested.
struct AyurvedaData {
    let otc: OTCFile
    let herbFile: HerbFile
    let medicines: [Medicine]

    /// Normalised name or alias -> indices into `medicines`.
    private let nameIndex: [String: [Int]]
    /// Longest names first, for finding a medicine inside scanned label text.
    private let namesByLength: [String]

    enum LoadError: Error { case missingResource(String) }

    /// Loads the JSON embedded at the bottom of this file. No bundle resources needed.
    init() throws {
        try self.init(otcData: Data(EmbeddedAyurvedaJSON.otc.utf8),
                      herbData: Data(EmbeddedAyurvedaJSON.herbs.utf8),
                      medicineData: Data(EmbeddedAyurvedaJSON.medicines.utf8))
    }

    init(bundle: Bundle) throws {
        func data(_ name: String) throws -> Data {
            guard let url = bundle.url(forResource: name, withExtension: "json") else {
                throw LoadError.missingResource("\(name).json")
            }
            return try Data(contentsOf: url)
        }
        try self.init(otcData: data("AyurvedaOTC"), herbData: data("HerbSafety"), medicineData: data("Medicines"))
    }

    init(otcData: Data, herbData: Data, medicineData: Data) throws {
        let decoder = JSONDecoder()
        otc = try decoder.decode(OTCFile.self, from: otcData)
        herbFile = try decoder.decode(HerbFile.self, from: herbData)
        medicines = try decoder.decode(MedicineFile.self, from: medicineData).medicines

        var index: [String: [Int]] = [:]
        for (i, m) in medicines.enumerated() {
            for name in [m.id, m.name] + m.aliases {
                let key = Self.normalise(name)
                guard key.count >= 3 else { continue }
                if index[key]?.contains(i) != true { index[key, default: []].append(i) }
            }
        }
        nameIndex = index
        namesByLength = index.keys.sorted { $0.count > $1.count }
    }

    var herbs: [Herb] { herbFile.herbs }
    var disclaimer: String { herbFile.disclaimer }

    func label(for drugClass: String) -> String {
        herbFile.drugClassLabels[drugClass] ?? drugClass
    }

    // MARK: Medicine search

    static func normalise(_ text: String) -> String {
        let folded = text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
        let cleaned = folded.unicodeScalars.map { CharacterSet.alphanumerics.contains($0) ? Character($0) : " " }
        return String(cleaned).split(separator: " ").joined(separator: " ")
    }

    /// Type-ahead search: names starting with the query first, then names containing it.
    func searchMedicines(_ query: String, limit: Int = 25) -> [Medicine] {
        let q = Self.normalise(query)
        guard q.count >= 2 else { return [] }
        var seen = Set<Int>()
        var prefix: [Int] = []
        var contains: [Int] = []
        for (key, ids) in nameIndex {
            if key.hasPrefix(q) {
                for i in ids where seen.insert(i).inserted { prefix.append(i) }
            } else if key.contains(q) {
                for i in ids where seen.insert(i).inserted { contains.append(i) }
            }
        }
        let byName: (Int, Int) -> Bool = { medicines[$0].name.count < medicines[$1].name.count }
        return (prefix.sorted(by: byName) + contains.sorted(by: byName)).prefix(limit).map { medicines[$0] }
    }

    /// Finds medicines named in text read from a strip or box (on-device OCR).
    /// Indian labels print the generic name prominently (Drugs Rules 1945, Rule 96).
    func medicines(inScannedText text: String) -> [Medicine] {
        let haystack = " " + Self.normalise(text) + " "
        var found: [Int] = []
        var covered = haystack
        for key in namesByLength where key.count >= 4 {
            let needle = " " + key + " "
            guard let range = covered.range(of: needle) else { continue }
            for i in nameIndex[key] ?? [] where !found.contains(i) { found.append(i) }
            // Blank out the match so "metformin" is not found again inside a longer name.
            covered.replaceSubrange(range, with: String(repeating: " ", count: needle.count))
        }
        return found.map { medicines[$0] }
    }

    // MARK: Herb warnings for a medicine

    func warnings(for medicine: Medicine) -> [HerbWarning] {
        let classes = Set(medicine.classes)
        guard !classes.isEmpty else { return [] }
        var result: [HerbWarning] = []
        for herb in herbs {
            var best: HerbWarning?
            for it in herb.interactions where classes.contains(it.drugClass) {
                if let only = it.onlyMolecules, !only.contains(medicine.id) { continue }
                var severity = it.severity
                if let majors = it.majorOnlyFor, !majors.contains(medicine.id), severity == .major {
                    severity = .moderate
                }
                if best == nil || severity > best!.severity {
                    best = HerbWarning(herb: herb, interaction: it, severity: severity)
                }
            }
            if let best { result.append(best) }
        }
        return result.sorted {
            $0.severity != $1.severity ? $0.severity > $1.severity : $0.herb.name < $1.herb.name
        }
    }

    /// Warnings grouped for display: severity, then drug class within it.
    func groupedWarnings(for medicine: Medicine) -> [(severity: Severity, groups: [(drugClass: String, warnings: [HerbWarning])])] {
        let all = warnings(for: medicine)
        return Severity.allCases.sorted(by: >).compactMap { sev in
            let items = all.filter { $0.severity == sev }
            guard !items.isEmpty else { return nil }
            let byClass = Dictionary(grouping: items, by: { $0.interaction.drugClass })
            let groups = byClass.keys.sorted { label(for: $0) < label(for: $1) }.map { (drugClass: $0, warnings: byClass[$0]!) }
            return (severity: sev, groups: groups)
        }
    }

    // MARK: Herbs and complaints

    func searchHerbs(_ query: String) -> [Herb] {
        let q = Self.normalise(query)
        guard !q.isEmpty else { return herbs }
        return herbs.filter { h in
            let names = [h.id, h.name, h.nameHi ?? "", h.sanskrit ?? "", h.latin ?? ""] + h.otherNames + h.commonProducts
            return names.contains { Self.normalise($0).contains(q) || $0.contains(query) }
        }
    }

    func searchComplaints(_ query: String) -> [OTCComplaint] {
        let q = Self.normalise(query)
        guard !q.isEmpty else { return otc.complaints }
        return otc.complaints.filter { c in
            Self.normalise(c.title).contains(q) || (c.titleHi ?? "").contains(query)
                || Self.normalise(c.otcMedicinesUsuallyUsed).contains(q)
                || c.options.contains { Self.normalise($0.name).contains(q) || ($0.nameHi ?? "").contains(query) }
        }
    }
}

// MARK: - ======================== SwiftUI screens ========================

#if canImport(SwiftUI)
// MARK: - Store

/// Loads the bundled JSON once, off the main thread. Inject at the app root:
///   AyurvedaHomeView().environmentObject(AyurvedaStore())
@MainActor
final class AyurvedaStore: ObservableObject {
    @Published private(set) var data: AyurvedaData?
    @Published private(set) var loadError: String?

    init() {
        Task { await load() }
    }

    func load() async {
        do {
            let loaded = try await Task.detached(priority: .userInitiated) { try AyurvedaData() }.value
            data = loaded
        } catch {
            loadError = "Couldn't load Ayurveda data (\(error)). Check the JSON files are in the app target."
        }
    }
}

// MARK: - Home

struct AyurvedaHomeView: View {
    @EnvironmentObject private var store: AyurvedaStore

    var body: some View {
        NavigationStack {
            Group {
                if let data = store.data {
                    List {
                        Section {
                            NavigationLink {
                                ComplaintListView(data: data)
                            } label: {
                                HomeRow(title: "Traditional Ayurvedic options",
                                        subtitle: "For \(data.otc.complaints.count) everyday complaints",
                                        hindi: "आयुर्वेदिक पारंपरिक विकल्प", systemImage: "leaf")
                            }
                            NavigationLink {
                                MedicineSearchView(data: data)
                            } label: {
                                HomeRow(title: "Herb safety for my medicine",
                                        subtitle: "Which herbs to be careful with",
                                        hindi: "मेरी दवा के साथ जड़ी-बूटी सुरक्षा", systemImage: "pills")
                            }
                            NavigationLink {
                                HerbListView(data: data)
                            } label: {
                                HomeRow(title: "Herb and product safety",
                                        subtitle: "\(data.herbs.count) herbs, formulations and bhasmas",
                                        hindi: "जड़ी-बूटी और उत्पाद सुरक्षा", systemImage: "list.bullet.rectangle")
                            }
                        }
                        Section {
                            DisclaimerText(text: data.disclaimer)
                        }
                    }
                } else if let error = store.loadError {
                    ContentUnavailableCompat(title: "Data not loaded", message: error)
                } else {
                    ProgressView("Loading…")
                }
            }
            .navigationTitle("Ayurveda")
        }
    }
}

private struct HomeRow: View {
    let title: String
    let subtitle: String
    let hindi: String
    let systemImage: String

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: systemImage).font(.title3).foregroundStyle(.green).frame(width: 28)
            VStack(alignment: .leading, spacing: 2) {
                Text(title).font(.headline)
                Text(hindi).font(.subheadline).foregroundStyle(.secondary)
                Text(subtitle).font(.caption).foregroundStyle(.secondary)
            }
        }
        .padding(.vertical, 4)
    }
}

// MARK: - Complaints → classical options

struct ComplaintListView: View {
    let data: AyurvedaData
    @State private var query = ""

    var body: some View {
        List(data.searchComplaints(query)) { complaint in
            NavigationLink {
                ComplaintDetailView(complaint: complaint, disclaimer: data.otc.disclaimer)
            } label: {
                VStack(alignment: .leading, spacing: 2) {
                    Text(complaint.title).font(.body.weight(.semibold))
                    if let hi = complaint.titleHi { Text(hi).font(.subheadline).foregroundStyle(.secondary) }
                    Text("\(complaint.options.count) options").font(.caption).foregroundStyle(.secondary)
                }
            }
        }
        .searchable(text: $query, prompt: "Search: acidity, खांसी, triphala…")
        .navigationTitle("Everyday complaints")
    }
}

struct ComplaintDetailView: View {
    let complaint: OTCComplaint
    let disclaimer: String

    var body: some View {
        List {
            Section {
                DisclaimerText(text: disclaimer)
            }
            Section("Usually treated with (OTC)") {
                Text(complaint.otcMedicinesUsuallyUsed).font(.subheadline)
            }
            Section("Traditional Ayurvedic options") {
                ForEach(complaint.options) { option in
                    OptionRow(option: option)
                }
            }
            Section {
                Label {
                    Text("See a doctor if: \(complaint.seeADoctorIf)").font(.subheadline)
                } icon: {
                    Image(systemName: "exclamationmark.triangle.fill").foregroundStyle(.red)
                }
            }
            Section("Source") {
                Text(complaint.source).font(.caption).foregroundStyle(.secondary).textSelection(.enabled)
            }
        }
        .navigationTitle(complaint.title)
        .navigationBarTitleDisplayMode(.inline)
    }
}

private struct OptionRow: View {
    let option: OTCOption
    @State private var expanded = false

    var body: some View {
        DisclosureGroup(isExpanded: $expanded) {
            Text(option.caution).font(.footnote).foregroundStyle(.secondary).padding(.vertical, 4)
        } label: {
            VStack(alignment: .leading, spacing: 2) {
                Text(option.name).font(.body.weight(.medium))
                if let hi = option.nameHi { Text(hi).font(.subheadline).foregroundStyle(.secondary) }
                Text("\(option.form) · \(option.howUsed)").font(.caption).foregroundStyle(.secondary)
            }
        }
    }
}

// MARK: - Medicine → herb warnings

struct MedicineSearchView: View {
    let data: AyurvedaData
    @State private var query = ""

    var body: some View {
        List {
            if query.count < 2 {
                Section {
                    Text("Type the generic name printed on your strip, e.g. metformin, paracetamol, amlodipine.")
                        .font(.subheadline).foregroundStyle(.secondary)
                }
            } else {
                let results = data.searchMedicines(query)
                if results.isEmpty {
                    Text("No medicine found. Try the generic name printed under the brand name.")
                        .foregroundStyle(.secondary)
                }
                ForEach(results) { medicine in
                    NavigationLink {
                        MedicineSafetyView(data: data, medicine: medicine)
                    } label: {
                        VStack(alignment: .leading, spacing: 2) {
                            Text(medicine.name.capitalized).font(.body.weight(.medium))
                            Text(medicine.classes.isEmpty ? "No known herb interactions in our data"
                                 : medicine.classes.map(data.label(for:)).joined(separator: " · "))
                                .font(.caption).foregroundStyle(.secondary).lineLimit(2)
                        }
                    }
                }
            }
        }
        .searchable(text: $query, prompt: "Search a medicine")
        .autocorrectionDisabled()
        .navigationTitle("My medicine")
    }
}

struct MedicineSafetyView: View {
    let data: AyurvedaData
    let medicine: Medicine

    var body: some View {
        let grouped = data.groupedWarnings(for: medicine)
        List {
            Section {
                VStack(alignment: .leading, spacing: 6) {
                    Text(medicine.name.capitalized).font(.title2.bold())
                    if !medicine.classes.isEmpty {
                        Text(medicine.classes.map(data.label(for:)).joined(separator: " · "))
                            .font(.subheadline).foregroundStyle(.secondary)
                    }
                }
                DisclaimerText(text: data.disclaimer)
            }
            if grouped.isEmpty {
                Section {
                    Text("No known herb interactions in our data. That doesn't mean a combination is safe. Ask your pharmacist before adding any herbal product.")
                        .font(.subheadline)
                }
            }
            ForEach(grouped, id: \.severity) { block in
                Section {
                    if block.severity == .minor {
                        DisclosureGroup("Show \(block.groups.reduce(0) { $0 + $1.warnings.count }) lower-evidence interactions") {
                            warningRows(block.groups)
                        }
                    } else {
                        warningRows(block.groups)
                    }
                } header: {
                    SeverityHeader(severity: block.severity)
                }
            }
        }
        .navigationTitle(medicine.name.capitalized)
        .navigationBarTitleDisplayMode(.inline)
    }

    @ViewBuilder
    private func warningRows(_ groups: [(drugClass: String, warnings: [HerbWarning])]) -> some View {
        ForEach(groups, id: \.drugClass) { group in
            if groups.count > 1 {
                Text(data.label(for: group.drugClass)).font(.caption.weight(.semibold)).foregroundStyle(.secondary)
            }
            ForEach(group.warnings) { warning in
                NavigationLink {
                    HerbDetailView(data: data, herb: warning.herb)
                } label: {
                    WarningRow(warning: warning)
                }
            }
        }
    }
}

private struct SeverityHeader: View {
    let severity: Severity

    var body: some View {
        HStack(spacing: 8) {
            Text(severity.title.uppercased())
                .font(.caption2.bold())
                .padding(.horizontal, 6).padding(.vertical, 2)
                .background(severity.color.opacity(0.18), in: RoundedRectangle(cornerRadius: 4))
                .foregroundStyle(severity.color)
            Text(severity.subtitle).font(.caption)
        }
    }
}

private struct WarningRow: View {
    let warning: HerbWarning

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack(alignment: .firstTextBaseline) {
                Text(warning.herb.name).font(.body.weight(.semibold))
                if let hi = warning.herb.nameHi { Text(hi).font(.subheadline).foregroundStyle(.secondary) }
            }
            Text(warning.interaction.effect).font(.subheadline)
            if let advice = warning.interaction.advice {
                Text(advice).font(.caption).foregroundStyle(.secondary)
            }
            if let evidence = warning.interaction.evidence {
                Text("Evidence: \(evidence.replacingOccurrences(of: "_", with: " "))")
                    .font(.caption2).foregroundStyle(.secondary)
            }
        }
        .padding(.vertical, 2)
    }
}

// MARK: - Herbs

struct HerbListView: View {
    let data: AyurvedaData
    @State private var query = ""

    var body: some View {
        List(data.searchHerbs(query)) { herb in
            NavigationLink {
                HerbDetailView(data: data, herb: herb)
            } label: {
                VStack(alignment: .leading, spacing: 2) {
                    HStack(alignment: .firstTextBaseline) {
                        Text(herb.name).font(.body.weight(.medium))
                        if let hi = herb.nameHi { Text(hi).font(.subheadline).foregroundStyle(.secondary) }
                    }
                    Text("\(herb.kindLabel) · \(herb.interactions.count) interactions · data: \(herb.dataQuality)")
                        .font(.caption).foregroundStyle(.secondary)
                }
            }
        }
        .searchable(text: $query, prompt: "Search: ashwagandha, गिलोय, Liv.52…")
        .navigationTitle("Herbs")
    }
}

struct HerbDetailView: View {
    let data: AyurvedaData
    let herb: Herb

    var body: some View {
        List {
            Section {
                VStack(alignment: .leading, spacing: 4) {
                    if let hi = herb.nameHi { Text(hi).font(.title3) }
                    if let latin = herb.latin { Text(latin).font(.subheadline).italic().foregroundStyle(.secondary) }
                    Text("\(herb.kindLabel) · evidence quality: \(herb.dataQuality)").font(.caption).foregroundStyle(.secondary)
                }
                if let context = herb.traditionalContext {
                    Text(context + (herb.isAyurvedic ? "" : " (Not an Ayurvedic herb; listed because it is often sold alongside Ayurvedic products.)"))
                        .font(.subheadline)
                }
                DisclaimerText(text: data.disclaimer)
            }
            if !herb.herbWarnings.isEmpty {
                Section("Important") {
                    ForEach(herb.herbWarnings, id: \.self) { w in
                        Label(w.effect, systemImage: "exclamationmark.octagon.fill")
                            .foregroundStyle(w.severity.color)
                    }
                }
            }
            if !herb.safetyFlags.isEmpty {
                Section("Safety") {
                    ForEach(herb.safetyFlags, id: \.self) { flag in
                        VStack(alignment: .leading, spacing: 2) {
                            Text(flag.flag.replacingOccurrences(of: "_", with: " ").capitalized).font(.subheadline.weight(.semibold))
                            Text(flag.note).font(.subheadline)
                            SourceLinks(urls: flag.sources)
                        }
                    }
                }
            }
            Section("Medicines to be careful with") {
                if herb.interactions.isEmpty {
                    Text("No documented interactions found.").foregroundStyle(.secondary)
                }
                ForEach(herb.interactions.sorted { $0.severity > $1.severity }, id: \.self) { it in
                    VStack(alignment: .leading, spacing: 3) {
                        HStack {
                            Text(data.label(for: it.drugClass)).font(.subheadline.weight(.semibold))
                            Spacer()
                            Text(it.severity.title).font(.caption2.bold()).foregroundStyle(it.severity.color)
                        }
                        Text(it.effect).font(.subheadline)
                        SourceLinks(urls: it.sources)
                    }
                }
            }
            if !herb.commonProducts.isEmpty {
                Section("Common products") {
                    Text(herb.commonProducts.joined(separator: ", ")).font(.footnote).foregroundStyle(.secondary)
                }
            }
        }
        .navigationTitle(herb.name)
        .navigationBarTitleDisplayMode(.inline)
    }
}

// MARK: - Shared pieces

private struct SourceLinks: View {
    let urls: [String]

    var body: some View {
        HStack(spacing: 10) {
            ForEach(Array(urls.prefix(3).enumerated()), id: \.offset) { index, string in
                if let url = URL(string: string) {
                    Link("Source \(index + 1)", destination: url).font(.caption)
                }
            }
        }
    }
}

struct DisclaimerText: View {
    let text: String

    var body: some View {
        Label {
            Text(text).font(.footnote)
        } icon: {
            Image(systemName: "info.circle").foregroundStyle(.orange)
        }
    }
}

/// ContentUnavailableView is iOS 17+; this keeps the screen working on iOS 16.
private struct ContentUnavailableCompat: View {
    let title: String
    let message: String

    var body: some View {
        VStack(spacing: 8) {
            Image(systemName: "exclamationmark.triangle").font(.largeTitle).foregroundStyle(.secondary)
            Text(title).font(.headline)
            Text(message).font(.subheadline).foregroundStyle(.secondary).multilineTextAlignment(.center)
        }
        .padding()
    }
}

extension Severity {
    var color: Color {
        switch self {
        case .major: return .red
        case .moderate: return .orange
        case .minor: return .secondary
        }
    }
}

struct AyurvedaHomeView_Previews: PreviewProvider {
    static var previews: some View {
        AyurvedaHomeView().environmentObject(AyurvedaStore())
    }
}
#endif

